"use strict";(globalThis.webpackChunkgrc||=[]).push([[1813],{83492(e){e.exports=JSON.parse('{"citeKey":"chen2006stas","slug":"chen-2006-stas-c70d","title":"STAS: A Scalability Testing and Analysis System","authors":["Y. Chen","X.-H. Sun"],"venue":"The IEEE International conference on Cluster Computing 2006(Cluster2006)","type":"Conference","entryType":"inproceedings","date":"January, 2006","year":2006,"era":"iit","month":1,"doi":"10.1109/clustr.2006.311882","abstract":"Scalability is a crucial factor in performance evaluation and analysis of parallel and distributed systems. Much effort has been devoted to scalability research and several metrics are proposed. However, the lacking of an effective scalability analysis toolkit is still a major barrier for researchers to measure and analyze scalabilities. Isospeed scalability is a known metric and has been extended for general computing systems recently. This paper proposes an effective Scalability Testing and Analysis System, called STAS, and presents its implementation with isospeed-e scalability metric. STAS provides the facility to conduct automated isospeed-e scalability measure and analysis. It reduces the burden for users to evaluate the performance of algorithms and systems. Experiments have been conducted to verify the design and implementation.","hasAbstract":true,"lede":"This paper proposes an effective Scalability Testing and Analysis System, called STAS, and presents its implementation with isospeed-e scalability metric.","links":{"pdf":"https://grc.iit.edu/papers/2006/chen-2006-stas-c70d.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);